'use strict';
// Isolated Phase 02 design study. Synthetic facts, not an ephemeris or birth calculator.
const main = document.querySelector('#main');
const signs = ['Bạch Dương','Kim Ngưu','Song Tử','Cự Giải','Sư Tử','Xử Nữ','Thiên Bình','Bọ Cạp','Nhân Mã','Ma Kết','Bảo Bình','Song Ngư'];
const glyphs = ['♈','♉','♊','♋','♌','♍','♎','♏','♐','♑','♒','♓'].map(glyph=>glyph+'\uFE0E');
const bodies = [
 {id:'sun',name:'Mặt Trời',glyph:'☉',lon:42,r:174,meaning:'Trong chiêm tinh, Kim Ngưu thường gắn với sự bền bỉ và nhu cầu tạo nền tảng ổn định.'},
 {id:'moon',name:'Mặt Trăng',glyph:'☽',lon:137,r:205,meaning:'Mặt Trăng Sư Tử được liên hệ với nhu cầu được nhìn nhận và bộc lộ cảm xúc sáng tạo.'},
 {id:'mercury',name:'Sao Thủy',glyph:'☿',lon:59,r:222,meaning:'Biểu tượng của cách suy nghĩ, học hỏi và trao đổi. Đây là một cách diễn giải, không phải chẩn đoán.'},
 {id:'venus',name:'Sao Kim',glyph:'♀',lon:15,r:215,meaning:'Gợi suy ngẫm về giá trị, sự hấp dẫn và cách kết nối.'},
 {id:'mars',name:'Sao Hỏa',glyph:'♂',lon:102,r:158,meaning:'Gợi cách chủ động, sử dụng năng lượng và bảo vệ điều mình quan tâm.'},
 {id:'jupiter',name:'Sao Mộc',glyph:'♃',lon:263,r:202,meaning:'Biểu tượng của sự mở rộng, học hỏi và niềm tin.'},
 {id:'saturn',name:'Sao Thổ',glyph:'♄',lon:17,r:140,meaning:'Biểu tượng của giới hạn, trách nhiệm và quá trình xây dựng lâu dài.'},
 {id:'uranus',name:'Thiên Vương',glyph:'♅',lon:318,r:174,meaning:'Gợi ý suy ngẫm về sự thay đổi và độc lập; không phải dự báo sự kiện.'},
 {id:'neptune',name:'Hải Vương',glyph:'♆',lon:306,r:220,meaning:'Biểu tượng của tưởng tượng và lý tưởng, cần đọc cùng toàn bộ chart.'},
 {id:'pluto',name:'Diêm Vương',glyph:'♇',lon:250,r:142,meaning:'Biểu tượng của chuyển biến sâu và việc nhìn lại những khuôn mẫu.'}
];
const aspects = [
 {id:'sun-mars-sextile',a:'sun',b:'mars',name:'Lục hợp',angle:60,orb:0},
 {id:'sun-moon-square',a:'sun',b:'moon',name:'Vuông',angle:90,orb:5},
 {id:'moon-saturn-trine',a:'moon',b:'saturn',name:'Tam hợp',angle:120,orb:0}
]; // Deliberately limited synthetic aspect fixture; not an exhaustive calculated chart.
const state = {view:'chart',selected:'sun',zoom:100,advanced:false,unknown:false,logged:false,saved:false,deleting:false,tone:'plain',sign:1};
function point(lon,r){const a=(lon-196+180)*Math.PI/180;return [320+r*Math.cos(a),320-r*Math.sin(a)];}
function nodePoint(b,constellation){return point(b.lon,constellation?b.r:((bodies.indexOf(b)%2)?222:198));}
function fmt(b){return (b.lon%30)+'° '+signs[Math.floor(b.lon/30)];}
function sky(interactive=false,constellation=true){
 const lines = (state.unknown?[]:aspects).map(a=>{const p=nodePoint(bodies.find(b=>b.id===a.a),constellation),q=nodePoint(bodies.find(b=>b.id===a.b),constellation);return '<line class="chart-line" data-aspect="'+a.id+'" x1="'+p[0]+'" y1="'+p[1]+'" x2="'+q[0]+'" y2="'+q[1]+'"/>';}).join('');
 let rings='<circle class="ring" cx="320" cy="320" r="278"/><circle class="ring" cx="320" cy="320" r="236"/>';
 if(!constellation){
  rings+=signs.map((s,i)=>{const a=point(i*30,236),b=point(i*30,278),t=point(i*30+15,257);return '<path class="ring" d="M'+a.join(' ')+'L'+b.join(' ')+'"/><text class="svg-strong" text-anchor="middle" dominant-baseline="central" x="'+t[0]+'" y="'+t[1]+'">'+glyphs[i]+'</text>';}).join('');
  if(!state.unknown) rings+=signs.map((s,i)=>{const a=point(180+i*30,230),b=point(180+i*30,136),t=point(195+i*30,160);return '<path class="ring" d="M'+a.join(' ')+'L'+b.join(' ')+'"/><text class="svg-small" text-anchor="middle" x="'+t[0]+'" y="'+t[1]+'">'+(i+1)+'</text>';}).join('');
  if(!state.unknown){const p=point(196,290),m=point(97,290);rings+='<text class="svg-label" text-anchor="middle" x="'+p[0]+'" y="'+p[1]+'">ASC</text><text class="svg-label" text-anchor="middle" x="'+m[0]+'" y="'+m[1]+'">MC</text>';}
 }else{rings+='<ellipse class="ring" cx="320" cy="320" rx="300" ry="175" transform="rotate(-28 320 320)"/><circle class="ring" cx="320" cy="320" r="105"/>';}
 const nodes=bodies.map(b=>{const p=nodePoint(b,constellation);return '<g class="chart-node '+(state.selected===b.id?'selected':'')+'" data-body="'+b.id+'" '+(interactive?'tabindex="0" role="button" aria-label="'+b.name+', '+fmt(b)+'"':'aria-hidden="true"')+'><circle class="hit" cx="'+p[0]+'" cy="'+p[1]+'" r="23" fill="transparent"/><circle class="dot" cx="'+p[0]+'" cy="'+p[1]+'" r="'+(constellation?6:4)+'"/><text text-anchor="middle" x="'+p[0]+'" y="'+(p[1]-13)+'" font-size="'+(constellation?14:19)+'">'+(constellation?b.name:b.glyph)+'</text></g>';}).join('');
 return '<svg viewBox="0 0 640 640" role="'+(interactive?'group':'img')+'" aria-label="'+(constellation?'Liên kết sao biểu tượng':'Bản đồ sao dạng vòng')+' — dữ liệu tổng hợp" xmlns="http://www.w3.org/2000/svg">'+rings+lines+'<text class="chart-center" x="320" y="314" text-anchor="middle">TINH ĐỒ</text><text class="svg-small" x="320" y="338" text-anchor="middle">SYNTHETIC · 01</text>'+nodes+'</svg>';
}
function title(k,h,p){return '<div class="page-title"><div class="eyebrow">'+k+'</div><h1>'+h+'</h1><p class="lede">'+p+'</p></div>';}
function home(){return '<section class="hero orbit-panel"><aside class="hero-index">EXPLORATION / 01<br>01 · Bản đồ sao<br>02 · Những liên kết<br>03 · Hiểu chính mình<br><br>WESTERN ASTROLOGY<br>BEGINNER → ADVANCED</aside><div class="hero-copy"><div class="eyebrow">A personal atlas of the stars</div><h1>Giữa muôn vì sao,<br>tìm một <em>bản đồ<br>của riêng bạn.</em></h1><p class="lede">Khám phá những nét riêng qua bản đồ sao. Bắt đầu thật dễ hiểu, rồi đi sâu đến từng mối liên kết.</p><div class="actions"><a href="#create" class="button primary">Khám phá bản đồ sao ↗</a><a href="#learn" class="button">Tôi mới bắt đầu</a></div><small>Không cần tài khoản để xem thử · Minh bạch phương pháp</small></div><div class="hero-art">'+sky(false,true)+'<div class="art-caption">BẢN ĐỒ BIỂU TƯỢNG · DỮ LIỆU MINH HỌA</div></div></section><section class="section"><div class="section-head"><h2>Một bản đồ. Nhiều cách khám phá.</h2><a href="#chart">Xem bản mẫu ↗</a></div><div class="grid3"><article class="item"><span class="num">01 / KHỞI ĐẦU</span><h3>Bạn không chỉ là một cung.</h3><p>Big 3 mở ra ba góc nhìn: Mặt Trời, Mặt Trăng và cung Mọc.</p></article><article class="item"><span class="num">02 / ĐÀO SÂU</span><h3>Đi từ ý nghĩa đến dữ liệu.</h3><p>Đối chiếu hành tinh, nhà và góc hợp trên vòng natal chuẩn.</p></article><article class="item"><span class="num">03 / KẾT NỐI</span><h3>Đọc những mối liên kết.</h3><p>Khám phá lớp Liên kết sao và đặt câu hỏi với AI có dẫn chứng.</p></article></div></section>';}
function create(){return title('YOUR FIRST COORDINATES','Mọi hành trình bắt đầu<br>từ một khoảnh khắc.','Thông tin sinh giúp xác định vị trí thiên thể. Nếu chưa biết giờ, bạn vẫn có thể khám phá với giới hạn rõ ràng.')+'<div class="split"><form id="birth-form" class="panel" novalidate><div id="form-error" class="error hidden" tabindex="-1" role="alert"></div><div class="field"><label for="birth-date">Ngày sinh</label><input id="birth-date" type="date" min="1900-01-01" max="2026-10-21" required><small>Không nhập dữ liệu thật vào bản mẫu này.</small></div><div class="field"><label for="birth-time">Giờ sinh tại địa phương</label><input id="birth-time" type="time" value="08:30"></div><div class="check"><input id="unknown-time" type="checkbox" '+(state.unknown?'checked':'')+'><label for="unknown-time">Tôi không rõ giờ sinh</label></div><div class="field"><label for="birth-place">Nơi sinh — lựa chọn minh họa</label><select id="birth-place"><option>TP. Hồ Chí Minh · Asia/Ho_Chi_Minh</option><option>Hà Nội · Asia/Ho_Chi_Minh</option><option>London · Europe/London</option></select><small>Production cần xác nhận tọa độ, múi giờ lịch sử và DST.</small></div><div class="check"><input id="demo-consent" type="checkbox" required><label for="demo-consent">Tôi hiểu đây là bản mẫu, không tính chart từ dữ liệu nhập.</label></div><button class="primary" type="submit">Mở bản đồ minh họa ↗</button></form><aside><div class="eyebrow">PRIVACY BY INTENTION</div><h2>Thông tin của bạn,<br>quyền lựa chọn của bạn.</h2><p>Đề xuất sản phẩm: chart khách chỉ tồn tại tạm. Chỉ lưu vào tài khoản khi bạn chọn lưu, và hỏi riêng trước khi gửi dữ liệu sang AI.</p><div class="notice">Prototype không gửi form lên server, không gọi API, không ghi localStorage. Tất cả vị trí hiển thị là fixture tổng hợp.</div><p>Không rõ giờ → không có cung Mọc, MC và nhà. Những vị trí thay đổi trong khoảng ngày phải được ghi là chưa chắc chắn.</p></aside></div>';}
function big3(){return '<div class="big3"><div><span>☉ MẶT TRỜI / CỐT LÕI</span><strong>'+(state.unknown?'Chưa xác định':'Kim Ngưu')+'</strong><small>'+(state.unknown?'Cần tính khoảng ngày':'12° · fixture')+'</small></div><div><span>☽ MẶT TRĂNG / CẢM XÚC</span><strong>'+(state.unknown?'Chưa xác định':'Sư Tử')+'</strong><small>'+(state.unknown?'Cần tính khoảng ngày':'17° · fixture')+'</small></div><div><span>ASC / CÁCH HIỆN DIỆN</span><strong>'+(state.unknown?'Không có giờ':'Thiên Bình')+'</strong><small>'+(state.unknown?'Không tạo cung Mọc':'16° · fixture')+'</small></div></div>';}
function detail(){const b=bodies.find(b=>b.id===state.selected);return '<span class="tag">ĐIỂM ĐANG KHÁM PHÁ</span><h2>'+b.glyph+' '+b.name+'</h2><p>'+fmt(b)+(state.unknown?' · vị trí tham chiếu, không chắc chắn':' · fixture')+'</p><p>'+(state.unknown?'Chưa có kết quả khoảng ngày; không diễn giải cá nhân từ vị trí tham chiếu.':b.meaning)+'</p><code>fact: body:'+b.id+'<br>revision: synthetic-01</code><p class="chart-caption">Giải thích biểu tượng, không phải kết luận chắc chắn về con người.</p><h3>Liên kết trong bản mẫu</h3><ul>'+(state.unknown?[]:aspects).filter(a=>a.a===b.id||a.b===b.id).map(a=>'<li>'+a.name+' · '+a.angle+'° · orb '+a.orb+'°<br><span class="source">'+a.id+'</span></li>').join('')+'</ul><a href="#ai" class="button primary">Hỏi AI về điểm này ↗</a><div class="row"><button id="prev-node" type="button">← Điểm trước</button><button id="next-node" type="button">Điểm sau →</button></div>';}
function chart(){return title('PERSONAL STAR ATLAS / SYNTHETIC 01','Bản đồ sao của bạn','Một dữ liệu gốc, hai cách nhìn. Chọn một hành tinh để khám phá ý nghĩa và các mối liên kết.')+'<div class="notice">Bản mẫu tổng hợp, không phải chart đã tính từ ngày sinh. Tropical · Whole Sign minh họa; chưa chốt cấu hình sản phẩm. Chỉ 3 aspect mẫu, không phải toàn bộ góc hợp.</div>'+big3()+'<div class="toolbar"><div class="segments" aria-label="Cách hiển thị"><button data-view="chart" aria-pressed="'+(state.view==='chart')+'">Chart chuẩn</button><button data-view="constellation" aria-pressed="'+(state.view==='constellation')+'">Liên kết sao</button></div><div class="segments"><button id="expert" aria-pressed="'+state.advanced+'">'+(state.advanced?'Chuyên sâu':'Dễ hiểu')+'</button><button id="zoom-in" aria-label="Phóng to bản đồ">＋</button><button id="zoom-reset" aria-label="Đặt lại thu phóng">100%</button></div></div><p id="view-explanation" class="chart-caption">'+(state.view==='constellation'?'Phép chiếu biểu tượng từ kinh độ và góc hợp trong fixture. Không phải chòm sao thiên văn hay cây mở khóa.':'Vòng ngoài: 12 cung hoàng đạo. Vòng trong: 12 nhà khi có giờ. Các điểm: hành tinh.')+'</p><div class="chart-layout"><div><div class="chart-stage" id="chart-stage" data-zoom="'+state.zoom+'" tabindex="0" aria-label="Vùng bản đồ, có thể cuộn khi phóng to">'+sky(true,state.view==='constellation')+'</div><p class="chart-caption">Chạm hoặc dùng Tab + Enter chọn điểm. Bảng dữ liệu ở dưới là cách đọc thay thế.</p><label class="check"><input id="chart-unknown" type="checkbox" '+(state.unknown?'checked':'')+'>Thử trạng thái không rõ giờ sinh</label></div><aside class="panel fact-panel" id="fact-panel" aria-label="Chi tiết điểm đã chọn">'+detail()+'</aside></div><div class="data-wrap"><table><caption>Vị trí tổng hợp — '+(state.unknown?'chỉ tham chiếu, cần engine tính khoảng':'Whole Sign minh họa')+'</caption><thead><tr><th>Hành tinh</th><th>Vị trí</th>'+(state.advanced?'<th>Nhà minh họa</th><th>Fact ID</th>':'')+'</tr></thead><tbody>'+bodies.map(b=>'<tr><td>'+b.name+'</td><td>'+fmt(b)+(state.unknown?' · tham chiếu':'')+'</td>'+(state.advanced?'<td>'+(state.unknown?'Không có':((Math.floor(b.lon/30)-6+12)%12+1))+'</td><td>body:'+b.id+'</td>':'')+'</tr>').join('')+'</tbody></table></div><div class="actions"><button id="save-chart" class="primary">Lưu vào hồ sơ sao</button><a href="#create" class="button">Thay thông tin</a></div>';}
function ai(){return title('AI ASTROLOGER / MOCK','Đặt câu hỏi.<br>Tìm về dữ liệu.','Hai giọng kể, cùng một bản đồ sao. AI không tính vị trí hành tinh và không biết tương lai của bạn.')+'<div class="ai-layout"><aside><span class="tag">MOCK · KHÔNG API</span><h2 style="margin-top:22px">Hồ sơ minh họa</h2><p>synthetic-01<br>Điểm chọn: '+bodies.find(b=>b.id===state.selected).name+'</p><label for="tone">Cách diễn giải</label><select id="tone"><option value="plain">Dễ hiểu</option><option value="mystical">Kể chuyện sao</option></select><p class="chart-caption">Tone chỉ đổi cách kể. Facts và mức chắc chắn giữ nguyên.</p><a href="#chart" class="inline-link">Xem chart và bằng chứng ↗</a></aside><section><div class="notice">Phản hồi soạn sẵn cho fixture, không phải AI thật. Không nhập thông tin riêng tư.</div><div id="chat-log" aria-live="polite"><div class="chat-message"><strong>NGƯỜI ĐỒNG HÀNH</strong><p>Bạn muốn khám phá điều gì từ điểm đang chọn? Tôi có thể giải thích ý nghĩa biểu tượng và chỉ ra dữ liệu được dùng.</p></div></div><form id="chat-form" class="chat-compose"><label for="question">Câu hỏi của bạn</label><textarea id="question" required maxlength="500" placeholder="Điểm này được hiểu như thế nào?"></textarea><div class="actions"><button type="submit" class="primary">Gửi câu hỏi mẫu ↗</button></div></form></section></div>';}
function dashboard(){return title('YOUR COLLECTION','Hồ sơ sao','Lưu những bản đồ bạn muốn quay lại. Bạn quyết định điều gì được giữ và điều gì được xóa.')+(state.logged?'<span class="tag">PHIÊN ĐĂNG NHẬP GIẢ LẬP · CHỈ TRONG BỘ NHỚ</span>':'<div class="notice">Khách vẫn có thể đọc chart. Sản phẩm đề xuất yêu cầu tài khoản để lưu/sync và quản lý quota AI.</div><button id="mock-login" class="primary">Thử đăng nhập giả lập</button>')+'<section class="section"><div class="section-head"><h2>Những bản đồ của bạn</h2><a href="#create">+ Thêm bản đồ</a></div>'+(state.saved?'<div class="profile-row"><div><h3>Bản đồ minh họa 01</h3><p>Tropical · Whole Sign fixture · synthetic-01</p></div><div class="actions"><a href="#chart" class="button">Mở chart</a><button id="delete-chart">Xóa bản mẫu</button></div></div>':'<div class="item"><h3>Chưa có hồ sơ được lưu.</h3><p>Khám phá chart trước, rồi chọn lưu nếu bạn muốn.</p><a class="button" href="#chart">Xem bản đồ mẫu ↗</a></div>')+(state.deleting?'<div class="notice" role="alert">Xóa hồ sơ minh họa khỏi bộ nhớ phiên này?<div class="actions"><button id="confirm-delete">Xác nhận xóa</button><button id="cancel-delete">Giữ lại</button></div></div>':'')+'</section>';}
function zodiac(){return title('TWELVE SIGNS, MANY STORIES','12 cung hoàng đạo','Cánh cửa đầu tiên để làm quen, không phải toàn bộ con người bạn.')+'<div class="zodiac-grid">'+signs.map((s,i)=>'<button class="zodiac-card" data-sign="'+i+'" aria-pressed="'+(state.sign===i)+'"><span aria-hidden="true">'+glyphs[i]+'</span>'+s+'</button>').join('')+'</div><section class="section article"><div class="eyebrow">ĐANG KHÁM PHÁ</div><h2>'+signs[state.sign]+'</h2><p>Nội dung mẫu: mỗi cung là một phần của ngôn ngữ biểu tượng chiêm tinh. Đừng suy ra toàn bộ tính cách, tình yêu hoặc nghề nghiệp từ một cung đơn lẻ.</p><p>Muốn biết Mặt Trời của mình ở đâu, nhất là gần ranh giới, cần tính từ thời điểm sinh bằng engine. “Cung” ở đây không phải nhà chiêm tinh hay con giáp.</p><a class="button primary" href="#create">Khám phá Big 3 ↗</a></section>';}
function learn(){return title('A SMALL GUIDE TO A VAST SKY','Không cần biết thuật ngữ<br>để bắt đầu khám phá.','Một hướng dẫn ngắn cho người mới. Nội dung hiện tại là mẫu bố cục, chưa phải thư viện hoàn chỉnh.')+'<article class="article"><div class="grid3"><div class="item"><span class="num">☉ / SUN</span><h3>Điều bạn hướng đến</h3><p>Mặt Trời thường tượng trưng cho bản sắc và cách thể hiện mình.</p></div><div class="item"><span class="num">☽ / MOON</span><h3>Điều bạn cần</h3><p>Mặt Trăng thường được đọc như nhu cầu cảm xúc.</p></div><div class="item"><span class="num">ASC / RISING</span><h3>Cách bạn hiện diện</h3><p>Cần giờ và nơi sinh; không thể khẳng định khi thiếu giờ.</p></div></div><h2>Hành tinh, cung, nhà và góc hợp</h2><p>Hành tinh là các điểm được tính. Cung là 12 phần bằng nhau của hoàng đạo theo hệ quy chiếu được chọn. Nhà là cách chia chart theo giờ/nơi và phương pháp. Góc hợp là quan hệ góc giữa các điểm, với orb được công bố.</p><h2>Một bản đồ biểu tượng, không phải lời phán</h2><p>Vị trí thiên thể có thể kiểm chứng bằng thiên văn. Ý nghĩa tính cách hoặc vận mệnh là diễn giải chiêm tinh, không đồng nghĩa bằng chứng khoa học. Không dùng để quyết định y tế, tài chính hoặc thay quyền lựa chọn của bạn.</p><h2>Liên kết sao hoạt động thế nào?</h2><p>Các node cùng fact ID với chart chuẩn; đường nối là góc hợp có dữ liệu. Bố trí biểu tượng không phải chòm sao thật, không có sao mở khóa và không ngẫu nhiên tạo lời giải thích.</p><a class="button primary" href="#chart">Xem dữ liệu mẫu ↗</a></article>';}
const pages={home,create,chart,ai,dashboard,zodiac,learn};
function announce(text){document.querySelector('#announcement').textContent=text;}
function setDetail(id){state.selected=id;document.querySelector('#fact-panel').innerHTML=detail();document.querySelectorAll('.chart-node').forEach(n=>n.classList.toggle('selected',n.dataset.body===id));wireDetail();announce('Đã chọn '+bodies.find(b=>b.id===id).name);}
function wireDetail(){document.querySelector('#prev-node')?.addEventListener('click',()=>setDetail(bodies[(bodies.findIndex(b=>b.id===state.selected)+9)%10].id));document.querySelector('#next-node')?.addEventListener('click',()=>setDetail(bodies[(bodies.findIndex(b=>b.id===state.selected)+1)%10].id));}
function render(){
 const route=location.hash.slice(1)||'home';const page=pages[route]||home;main.innerHTML=page();document.body.dataset.page=route;
 document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(route==='create'){
  const unknown=document.querySelector('#unknown-time'),time=document.querySelector('#birth-time');time.disabled=state.unknown;unknown.addEventListener('change',()=>{state.unknown=unknown.checked;time.disabled=state.unknown;});
  document.querySelector('#birth-form').addEventListener('submit',e=>{e.preventDefault();const date=document.querySelector('#birth-date'),consent=document.querySelector('#demo-consent');if(!date.value||!date.checkValidity()||(!state.unknown&&!time.value)||!consent.checked){const err=document.querySelector('#form-error');err.textContent='Chọn ngày hợp lệ (1900–21/10/2026), giờ hoặc không rõ giờ, và xác nhận bản mẫu.';err.classList.remove('hidden');err.focus();return;}location.hash='chart';});
 }
 if(route==='chart'){
  document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{state.view=b.dataset.view;state.zoom=100;render();}));
  document.querySelectorAll('[data-body]').forEach(n=>{n.addEventListener('click',()=>setDetail(n.dataset.body));n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setDetail(n.dataset.body);}});});
  document.querySelector('#expert').addEventListener('click',()=>{state.advanced=!state.advanced;render();});
  document.querySelector('#chart-unknown').addEventListener('change',e=>{state.unknown=e.target.checked;render();});
  document.querySelector('#zoom-in').addEventListener('click',()=>{state.zoom=Math.min(200,state.zoom+25);document.querySelector('#chart-stage').dataset.zoom=state.zoom;document.querySelector('#zoom-reset').textContent=state.zoom+'%';});
  document.querySelector('#zoom-reset').textContent=state.zoom+'%';
  document.querySelector('#zoom-reset').addEventListener('click',()=>{state.zoom=100;document.querySelector('#chart-stage').dataset.zoom=100;document.querySelector('#chart-stage').scrollTo(0,0);document.querySelector('#zoom-reset').textContent='100%';});
  document.querySelector('#save-chart').addEventListener('click',()=>{if(state.logged){state.saved=true;announce('Đã lưu bản mẫu trong bộ nhớ.');}location.hash='dashboard';});
  wireDetail();
 }
 if(route==='ai'){
  const tone=document.querySelector('#tone');tone.value=state.tone;tone.addEventListener('change',()=>{state.tone=tone.value;});
  document.querySelector('#chat-form').addEventListener('submit',e=>{e.preventDefault();const q=document.querySelector('#question');if(!q.value.trim())return;const b=bodies.find(b=>b.id===state.selected),log=document.querySelector('#chat-log');for(const [who,text]of [['BẠN',q.value],['NGƯỜI ĐỒNG HÀNH · MOCK',state.unknown?'Chưa biết giờ sinh: bản mẫu không đủ dữ liệu để diễn giải cá nhân. Production cần tính khoảng trước khi kết luận; không có ASC/MC/nhà.':(state.tone==='plain'?b.name+' ở '+fmt(b)+'. '+b.meaning:'Trong bản đồ biểu tượng này, '+b.name+' tại '+fmt(b)+' gợi một điểm sáng để tự suy ngẫm. '+b.meaning)+' Đây là diễn giải quy ước trên dữ liệu tổng hợp, không phải dự đoán chắc chắn.']]){const box=document.createElement('div');box.className='chat-message';const head=document.createElement('strong'),p=document.createElement('p');head.textContent=who;p.textContent=text;box.append(head,p);if(who!=='BẠN'){const a=document.createElement('a');a.href='#chart';a.className='source';a.textContent='Nguồn: body:'+b.id+' · synthetic-01 · '+(state.unknown?'bất định':'fixture');box.append(a);}log.append(box);}q.value='';});
 }
 if(route==='dashboard'){
  document.querySelector('#mock-login')?.addEventListener('click',()=>{state.logged=true;render();announce('Phiên đăng nhập giả lập, chưa lưu chart.');});
  document.querySelector('#delete-chart')?.addEventListener('click',()=>{state.deleting=true;render();});
  document.querySelector('#confirm-delete')?.addEventListener('click',()=>{state.saved=false;state.deleting=false;render();announce('Đã xóa bản mẫu.');});
  document.querySelector('#cancel-delete')?.addEventListener('click',()=>{state.deleting=false;render();});
 }
 if(route==='zodiac')document.querySelectorAll('[data-sign]').forEach(b=>b.addEventListener('click',()=>{state.sign=Number(b.dataset.sign);render();}));
}
document.querySelector('#concept').addEventListener('change',e=>{document.body.dataset.theme=e.target.value;announce('Đã đổi concept '+e.target.value.toUpperCase());});
window.addEventListener('hashchange',()=>{if(location.hash!=='#main')render();main.focus();window.scrollTo(0,0);});render();
